description:
Write `std::vector<std::string> splitCsv(const std::string& line)` that cuts a line at each comma.

A `std::istringstream` lets you read from a string as if it were `std::cin`, and `std::getline` accepts a third argument: the character to stop at.

```cpp
std::istringstream in{ line };
std::string field{};
while (std::getline(in, field, ',')) { ... }
```

solution.solution.cpp:
#include <sstream>
#include <string>
#include <vector>

std::vector<std::string> splitCsv(const std::string& line)
{
    std::vector<std::string> fields{};
    std::istringstream in{ line };
    std::string field{};
    while (std::getline(in, field, ','))
    {
        fields.push_back(field);
    }
    return fields;
}

unitTests:
using Fields = std::vector<std::string>;
TEST("three fields") { CHECK_EQ(splitCsv("red,green,blue"), (Fields{ "red", "green", "blue" })); }
TEST("spaces are kept, empty fields too") { CHECK_EQ(splitCsv("a, b,,c"), (Fields{ "a", " b", "", "c" })); }
TEST("one field and none") { CHECK_EQ(splitCsv("solo"), (Fields{ "solo" })); CHECK(splitCsv("").empty()); }

